(function(root){
  'use strict';
  const C=root.JourneyCore, h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name)=>'<svg class="j-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(root.JOURNEY_ICONS?.[name]||'')+'</svg>';
  const button=(action,text,extra='',cls='')=>`<button type="button" class="j-btn ${cls}" data-j-action="${action}" ${extra}>${text}</button>`;
  const options=(items,value)=>Object.entries(items).map(([v,label])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(label)}</option>`).join('');
  const a=(url,text)=>C.url(url)?`<a href="${h(C.url(url))}" target="_blank" rel="noopener noreferrer">${h(text)} ↗</a>`:'<span class="j-muted">未附来源链接</span>';
  const sources=[
    ['全国','国家公务员局','https://www.scs.gov.cn/','国考及招录专题入口'],
    ['湖南','湖南省人社厅','https://rst.hunan.gov.cn/','从官方通知进入公务员招录专题'],
    ['湖北','湖北省人事考试院','https://www.hbsrsksy.cn/','公务员考试通知及报名入口'],
    ['广东','广东组织工作网','https://www.gdzz.gov.cn/','广东省统一招录公告'],
    ['广州','广州市人社局','https://rsj.gz.gov.cn/ywzt/rszdgg/gwykl/','省考广州职位与机关公告；独立招录须另见公告'],
    ['深圳','深圳市考试院','https://hrss.sz.gov.cn/szksy/ztzl/gwyks/','省考深圳职位及单独招录公告']
  ];
  function mount(host,adapter={}){
    let data=C.blank(),activeId='',page='overview',pane='tasks',filter='all',stage=-1,storageError='',pendingImport=null;
    try{const raw=localStorage.getItem(C.KEY);if(raw)data=C.clean(JSON.parse(raw));}catch{storageError='本机存储暂不可读或旧记录损坏。已保留原始存储，请导出或检查后再恢复；当前修改不会自动覆盖它。';}
    host.classList.add('journey');
    const modal=document.createElement('dialog');modal.className='journey j-dialog';modal.id='journeyDialog';document.body.append(modal);
    const file=document.createElement('input');file.type='file';file.accept='.json';file.hidden=true;file.id='journeyImportFile';host.after(file);
    const status=document.createElement('div');status.id='journeyToast';status.className='j-toast';status.setAttribute('role','status');status.hidden=true;document.body.append(status);
    let toastTimer;function notify(text){status.textContent=text;status.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>status.hidden=true,7000);}
    function save(){data.updatedAt=new Date().toISOString();if(storageError){notify('自动保存未启用，请导出考程备份，避免关闭后丢失。');return;}try{localStorage.setItem(C.KEY,JSON.stringify(data));}catch{storageError='本机保存失败。当前记录仅在本页内存中，请立即导出备份。';notify(storageError);}}
    function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type})),el=document.createElement('a');el.href=u;el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
    function current(){return data.exams.find(e=>e.id===activeId);}
    function badge(t){const s=C.taskState(t);return `<span class="j-tag ${s.tone}">${h(s.label)}</span>`;}
    function open(title,body,submit){modal.innerHTML=`<header class="j-dialog-head"><div><div class="j-kicker">知国公 · 我的考程</div><h2>${h(title)}</h2></div>${button('close','×','aria-label="关闭对话框"')}</header>${body}<p class="j-error" id="journeyFormError" role="alert"></p>`;modal.showModal();const form=modal.querySelector('form');if(form)form.addEventListener('submit',ev=>{ev.preventDefault();try{submit(Object.fromEntries(new FormData(form)),form);}catch(err){modal.querySelector('#journeyFormError').textContent=err.message;}});}
    function close(){modal.close();}
    const active=()=>data.exams.filter(e=>e.lifecycle==='active');
    function metrics(){const all=C.tasks(data),soon=all.filter(x=>!C.complete(x.task)&&C.trusted(x.task)&&C.due(x.task)&&C.ms(C.due(x.task))>=Date.now()&&C.ms(C.due(x.task))-Date.now()<=7*864e5),attention=all.filter(x=>C.taskState(x.task).rank<=1),uncertain=all.filter(x=>!C.complete(x.task)&&C.due(x.task)&&!C.trusted(x.task));return `<div class="j-metrics">${[[active().length,'正在跟进','layers'],[soon.length,'七天内事项','calendar'],[attention.length,'需要处理','circle-alert'],[data.errors.filter(e=>!e.mastered&&e.next<=C.today()).length,'到期错题','notebook-pen']].map(([n,label,i])=>`<div>${icon(i)}<strong>${n}</strong><span>${label}</span></div>`).join('')}</div>${uncertain.length?`<div class="j-callout">有 ${uncertain.length} 项日期尚未核对，未计入已核实截止提醒。请进入考试档案补齐依据。</div>`:''}`;}
    function taskRow(e,t){return `<article class="j-taskrow"><div class="j-status-dot ${C.complete(t)?'complete':''}">${C.complete(t)?icon('check'):icon(t.kind==='exam'?'calendar':'circle')}</div><div class="j-tasktext"><strong>${h(t.title)}</strong><small>${h(e.title)}</small><div>${badge(t)} <span class="j-time">${h(C.fmt(C.due(t)))}</span></div></div>${button('edit-task','查看 / 办理',`data-exam="${h(e.id)}" data-task="${h(t.id)}"`)}</article>`;}
    function examCard(e){const p=C.progress(e),next=e.tasks.find(t=>!C.complete(t));return `<article class="j-examcard"><div class="j-cardhead"><span class="j-tag ${e.lifecycle==='active'?'green':'muted'}">${h(e.year)} ${h(e.type)}</span><small>${h(e.region||'地区未填')}</small></div><button class="j-cardtitle" data-j-action="open-exam" data-exam="${h(e.id)}">${h(e.title)} ${icon('arrow-up-right')}</button><p>${h(e.departmentCode&&e.positionCode?e.departmentCode+' / '+e.positionCode:e.batch||'尚未选定岗位')}</p><div class="j-progress" aria-label="流程完成 ${p.done} / ${p.total}"><span style="width:${p.total?p.done/p.total*100:0}%"></span></div><div class="j-cardfoot"><small>已办妥 ${p.done} / ${p.total}</small><span>${next?'下一步：'+h(next.title):'流程已逐项记录'}</span></div></article>`;}
    function overview(){
      const todo=C.upcoming(data),clashes=C.conflicts(data),next=todo[0];
      return `<section class="j-hero"><div><div class="j-kicker">ONE JOURNEY, EVERY STEP</div><h1>从报名，到下一站<span>。</span></h1><p>把每场考试、每个截止时间、每次进步，放在同一张桌上。</p><div class="j-hero-actions">${button('create',icon('plus')+' 添加一场考试','','primary')}${button('calendar',icon('calendar')+' 导出日历提醒')}</div></div><div class="j-hero-note"><span>下一步 · ${next?'需要你确认':'从这里开始'}</span><strong>${next?h(next.task.title):'建立你的第一份考程'}</strong><p>${next?h(next.exam.title):'已报名、正在选岗或等待公告，都可以加入。'}</p>${next?button('edit-task','查看办理事项 →',`data-exam="${h(next.exam.id)}" data-task="${h(next.task.id)}"`):button('create','创建考程 →')}</div></section>${metrics()}
      ${clashes.length?`<section class="j-callout danger"><b>发现 ${clashes.length} 组考试时间重叠</b>${clashes.slice(0,5).map(c=>`<p>${h(c.a.exam.title)} · ${h(c.a.task.title)} 与 ${h(c.b.exam.title)} · ${h(c.b.task.title)}。请核对考点与最新通知后取舍。</p>`).join('')}</section>`:''}
      <div class="j-columns"><section class="j-panel"><div class="j-sectionhead"><h2>${icon('list-checks')}行动清单</h2>${button('go-agenda','查看全部 →')}</div>${todo.length?todo.slice(0,5).map(x=>taskRow(x.exam,x.task)).join(''):`<div class="j-empty"><div class="j-empty-icon">${icon('compass')}</div><h3>每一步，都有着落</h3><p>新建考程后，报名、缴费、准考证和后续流程会出现在这里。<br>先记录真实进度，工作台再帮你排下一步。</p>${button('create','新建考试档案','','primary')}</div>`}</section><aside class="j-panel"><div class="j-sectionhead"><h2>使用小贴士</h2>${icon('sparkles')}</div><ol class="j-tips"><li><b>先把考试加进来</b><p>国考可使用已核验时间模板；省市考按公告补日期。</p></li><li><b>办完一项，再确认一项</b><p>提交、审核、缴费分别确认；日期过去不会自动打勾。</p></li><li><b>把提醒带到系统日历</b><p>导入 .ics 后检查提醒权限。网页关闭后不主动推送。</p></li></ol><div class="j-soft">数据保存在此浏览器，可导出备份带到另一台设备。分享工具文件不包含你的填报记录。</div></aside></div><div class="j-sectionhead"><h2>我的考试 <span class="j-muted">${data.exams.length}</span></h2>${button('go-exams','管理全部 →')}</div><div class="j-examgrid">${active().slice(0,4).map(examCard).join('')||'<p class="j-muted">暂未添加。也可以从职位详情中加入考程。</p>'}</div>`;
    }
    function exams(){const list=data.exams.filter(e=>filter==='all'||e.lifecycle===filter);return `<div class="j-pagehead"><div class="j-kicker">MY APPLICATIONS</div><h1>每场考试，一份档案。</h1><p>年份、招录批次和岗位分开保存。一个完整考程，从关注到报到。</p></div><div class="j-toolbar"><div class="j-pills">${[['all','全部'],['active','正在跟进'],['archived','已归档']].map(([v,label])=>button('exam-filter',label,`data-value="${v}" aria-pressed="${filter===v}"`,filter===v?'selected':'')).join('')}</div>${button('create','＋ 添加考试','','primary')}</div><div class="j-examgrid">${list.map(examCard).join('')||'<div class="j-empty">暂无考试档案。点击“添加考试”开始。</div>'}</div>`;}
    function agenda(){const list=C.upcoming(data).filter(x=>filter==='all'||filter==='known'&&C.trusted(x.task)&&C.due(x.task)||filter==='unknown'&&(!C.trusted(x.task)||!C.due(x.task)));return `<div class="j-pagehead"><div class="j-kicker">DEADLINES & ACTIONS · 北京时间</div><h1>重要节点，提前一步。</h1><p>先处理异常与逾期事项，再看临近截止。未知日期保留为空。</p></div><div class="j-toolbar"><div class="j-pills">${[['all','全部待办'],['known','已核对日期'],['unknown','待补日期 / 依据']].map(([v,label])=>button('agenda-filter',label,`data-value="${v}" aria-pressed="${filter===v}"`,filter===v?'selected':'')).join('')}</div>${button('calendar','导出已核对的日历')}</div><section class="j-panel">${list.map(x=>taskRow(x.exam,x.task)).join('')||'<div class="j-empty">当前没有符合此筛选的待办。</div>'}</section>`;}
    function detail(){const e=current();if(!e){page='exams';return exams();}const p=C.progress(e);return `<div class="j-detail-top">${button('go-exams','← 我的考试')}<div>${button('edit-exam','编辑档案')}${button('archive',e.lifecycle==='active'?'归档':'恢复跟进')}</div></div><div class="j-pagehead"><div class="j-kicker">${h(e.year)} / ${h(e.type)} / ${h(e.region)}</div><h1>${h(e.title)}</h1><p>${h(e.departmentCode&&e.positionCode?'部门 '+e.departmentCode+' · 职位 '+e.positionCode:e.batch)} · 已办妥 ${p.done} / ${p.total}</p>${e.note?'<p class="j-muted">'+h(e.note)+'</p>':''}</div><nav class="j-subnav" aria-label="考试档案">${[['tasks','流程清单'],['materials','材料准备'],['study','备考与错题'],['scores','成绩与复盘'],['sources','公告与依据']].map(([v,label])=>button('pane',label,`data-value="${v}" aria-pressed="${pane===v}"`,pane===v?'selected':'')).join('')}</nav>${({tasks:renderTasks,materials:renderMaterials,study:renderStudy,scores:renderScores,sources:renderSources}[pane]||renderTasks)(e)}`;}
    function renderTasks(e){return `<div class="j-flow"><aside class="j-stages">${button('stage','全部流程',`data-value="-1"`,stage===-1?'selected':'')}${C.stages.map((label,i)=>{const ts=e.tasks.filter(t=>t.stage===i);return button('stage',`<span>${String(i+1).padStart(2,'0')}</span>${label}<small>${ts.filter(C.complete).length}/${ts.length}</small>`,`data-value="${i}"`,stage===i?'selected':'');}).join('')}</aside><div>${C.stages.map((label,i)=>stage!==-1&&stage!==i?'':`<section class="j-panel j-stagepanel"><div class="j-sectionhead"><h2><span class="j-number">${String(i+1).padStart(2,'0')}</span>${label}</h2>${button('new-task','＋ 自定义事项',`data-stage="${i}"`)}</div>${e.tasks.filter(t=>t.stage===i).map(t=>`<article class="j-flowtask"><div class="j-flowline"><div><h3>${h(t.title)}</h3>${badge(t)}</div>${button('edit-task','编辑 / 办理',`data-exam="${h(e.id)}" data-task="${h(t.id)}"`)}</div><p>${h(t.hint)}</p><div class="j-flowmeta"><span>${icon('calendar')}${h(t.start?C.fmt(t.start)+(t.end?' → '+C.fmt(t.end):' 起'):t.end?'截止 '+C.fmt(t.end):'时间待公布')}</span>${t.place?'<span>'+icon('map-pin')+h(t.place)+'</span>':''}</div>${t.note?'<p class="j-tasknote">'+h(t.note)+'</p>':''}<div class="j-source">${a(t.source,'查看时间依据')}<span>${h(C.proof[t.proof])}</span>${t.completedAt?'<span>个人记录：'+h(t.completedAt.slice(0,10))+'</span>':''}</div></article>`).join('')}</section>`).join('')}</div></div>`;}
    function renderMaterials(e){return `<div class="j-callout">以下是准备建议，不是本岗位完整必交清单。请用本场公告和资格复审通知逐项确认。这里只保存准备状态和备注，不保存证件照片或号码。</div><section class="j-panel"><div class="j-sectionhead"><h2>材料清单</h2>${button('material-new','＋ 添加材料')}</div>${e.materials.map(m=>`<div class="j-material"><div><b>${h(m.name)}</b><small>${h(m.note||'可记录证明开具进度、材料保存位置等')}</small></div><span class="j-tag ${m.status==='todo'?'amber':'green'}">${h({todo:'未准备',ready:'已备齐',submitted:'已提交',na:'不适用'}[m.status])}</span>${button('material-edit','编辑',`data-id="${h(m.id)}"`)}</div>`).join('')}</section>`;}
    function renderStudy(e){const logs=data.logs.filter(l=>l.examId===e.id),errors=data.errors.filter(l=>l.examId===e.id&&!l.mastered).sort((a,b)=>a.next.localeCompare(b.next)),minutes=logs.reduce((n,l)=>n+l.minutes,0),count=logs.reduce((n,l)=>n+l.count,0),correct=logs.reduce((n,l)=>n+l.correct,0);return `<div class="j-toolbar"><p class="j-muted">刷题 → 记录错因 → 到期重做。1 / 3 / 7 天复习是学习安排，可重新开始。</p><div>${button('log-new','＋ 学习记录','','primary')}${button('error-new','＋ 错题卡')}</div></div><div class="j-study-stats"><div><b>${(minutes/60).toFixed(1)}</b><span>累计净学习小时</span></div><div><b>${count}</b><span>累计练习题数</span></div><div><b>${count?Math.round(correct/count*100)+'%':'—'}</b><span>记录题目正确率</span></div><div><b>${errors.filter(x=>x.next<=C.today()).length}</b><span>今天应重做</span></div></div><div class="j-columns"><section class="j-panel"><div class="j-sectionhead"><h2>错题复盘</h2></div>${errors.map(x=>`<article class="j-errorcard"><span class="j-tag ${x.next<=C.today()?'amber':'muted'}">${x.next<=C.today()?'到期复习':'下次 '+h(x.next)}</span><small>${h(x.subject)} · 第 ${x.round+1} 次复习</small><h3>${h(x.title)}</h3><p>${h(x.note)}</p><div>${button('review-ok','闭卷做对了',`data-id="${h(x.id)}"`)}${button('review-again','仍错 / 猜对',`data-id="${h(x.id)}"`)}</div></article>`).join('')||'<div class="j-empty">没有待复习错题。把做错、猜对、超时的题记下来，写清错因与下次如何识别。</div>'}<p class="j-muted">已完成三轮：${data.errors.filter(x=>x.examId===e.id&&x.mastered).length} 张；可在学习记录中继续检验迁移。</p></section><section class="j-panel"><h2>学习记录</h2>${logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(l=>`<article class="j-log"><b>${h(l.date)} · ${h(l.subject)}</b><p>${l.minutes} 分钟 · ${l.correct} / ${l.count} 题答对</p><p>${h(l.note)}</p>${button('log-delete','删除误记',`data-id="${h(l.id)}"`)}</article>`).join('')||'<div class="j-empty">先记一次真实练习，再根据错因调整时间。正确率不是预测考试分数。</div>'}</section></div>`;}
    function renderScores(e){return `<section class="j-panel"><div class="j-sectionhead"><h2>记录成绩和官方结果</h2>${button('score-edit','填写 / 修改','','primary')}</div><div class="j-study-stats">${[['aptitude','行测'],['essay','申论'],['special','专业科目'],['interview','面试']].map(([key,label])=>`<div><b>${h(e.scores[key]||'—')}</b><span>${label}</span></div>`).join('')}</div><p><b>本人记录的结果：</b>${h(e.scores.result)}</p><p class="j-whitespace">${h(e.scores.note||'记录成绩来源、进面情况、复盘和下一次调整。未填成绩不按零分处理。')}</p><div class="j-soft">单科分数按百分制记录；各场合成权重和合格要求不同，请以对应公告核算。本站不把竞争比换算成录取概率，也不会因分数自动标记录用。</div></section>`;}
    function renderSources(e){return `<div class="j-toolbar"><p>把公告与自己的处理结果留在一起，方便追溯。</p>${button('source-new','＋ 保存公告','','primary')}</div>${e.source?'<section class="j-panel">档案主来源：'+a(e.source,'打开公告')+'</section>':''}${e.sources.map(s=>`<article class="j-panel"><div class="j-sectionhead"><h2>${h(s.title)}</h2>${button('source-edit','编辑',`data-id="${h(s.id)}"`)}</div>${a(s.url,'打开原文')}<p class="j-muted">本人核对日期：${h(s.checked||'尚未核对')}</p><p class="j-whitespace">${h(s.note)}</p></article>`).join('')||'<div class="j-empty">暂无公告记录。保存原文链接、核对日期及与你有关的条款，再更新对应流程时间。</div>'}`;}
    function watch(){return `<div class="j-pagehead"><div class="j-kicker">OFFICIAL NOTICES</div><h1>关注公告，掌握节奏。</h1><p>湖南、湖北、广东及广州、深圳官方入口。网页不自动登录或抓取个人报名系统。</p></div><div class="j-callout">这里提供关注入口与记录工具，未接入自动公告推送。没有核验的新一轮报名日期保持为空；往年月份只能帮助安排关注。</div><div class="j-sourcegrid">${sources.map(([area,name,url,note])=>`<article class="j-panel"><span class="j-tag green">${area}</span><h2>${name}</h2><p>${note}</p>${a(url,'前往官方入口')}<div class="j-sourceaction">${button('watch-add','建立关注考程',`data-area="${area}"`)}</div></article>`).join('')}</div><section class="j-panel"><h2>拿到新公告后，花两分钟更新</h2><ol class="j-tips"><li>在考试档案中保存公告链接与原文要点，记录本人核对日期。</li><li>分别填写报名、审查、缴费、参加确认、准考证与考试时间。原文“24:00”按次日 00:00 录入。</li><li>只将核对过的准确时间加入日历；后续调整时重新导出并核对旧事件。</li></ol></section>`;}
    function settings(){return `<div class="j-pagehead"><div class="j-kicker">LOCAL FIRST</div><h1>数据随你走。</h1><p>无需账号，也不调用模型。设备之间通过备份迁移，日历负责系统提醒。</p></div><div class="j-sourcegrid"><section class="j-panel"><h2>${icon('download')}备份与恢复</h2><p>备份包含全部考试、材料状态、学习与错题、个人成绩。恢复前预览，并选择追加或覆盖。</p><div class="j-actions">${button('backup','导出考程备份','','primary')}${button('import','导入考程备份')}</div><p class="j-muted">考程备份与原有选岗条件备份相互独立；迁移整套工具时两份都要保存。</p></section><section class="j-panel"><h2>${icon('calendar')}系统日历提醒</h2><p>只导出当前跟进、未办妥且有核对依据的精确日期。默认提前 1 天、2 小时提醒，是否通知取决于系统日历设置。</p>${button('calendar','导出 .ics 日历')}</section><section class="j-panel"><h2>${icon('printer')}打印 / 保存 PDF</h2><p>可打印当前考试档案。浏览器打印窗口选择“另存为 PDF”。</p>${button('print','打印当前页面')}<p class="j-muted">请先打开需要打印的流程、材料或复盘页面。</p></section><section class="j-panel"><h2>${icon('shield-check')}本机保存与清理</h2><p>不会自动同步到云端。清理浏览器数据或换浏览器可能丢失记录，建议定期导出备份。</p>${button('clear','清空本机考程记录','','danger')}</section></div><details class="j-panel"><summary>版本、来源与开源许可</summary><p>招录工作台 v1 · 2026-10-29。流程为通用办理清单，具体规则以本场公告为准。</p><p>${a(root.ExamPolicy?.sources?.announcement?.url,'2027国考公告')} · ${a(root.ExamPolicy?.sources?.csrc?.url,'2027证监会公告')}</p><p>Lucide 图标采用 ISC 许可；部分 Feather 派生图标为 MIT。完整声明随离线文件内嵌保存。</p></details>`;}
    function render(){
      host.innerHTML=`<div class="j-shell"><header class="j-header"><div class="j-wordmark">${icon('compass')}<b>我的考程</b><span>国考 · 省考 · 市级招录</span></div><span class="j-date">${h(C.today())} · 北京时间</span></header><nav class="j-mainnav" aria-label="考程导航">${[['overview','layout-dashboard','总览'],['exams','layers','我的考试'],['agenda','calendar','节点日历'],['watch','radar','招考关注'],['settings','folder-lock','备份与提醒']].map(([v,i,label])=>button('page',icon(i)+label,`data-value="${v}" aria-pressed="${page===v||page==='detail'&&v==='exams'}"`,page===v||page==='detail'&&v==='exams'?'selected':'')).join('')}</nav>${storageError?'<div class="j-callout danger">'+h(storageError)+button('backup','导出当前记录')+'</div>':''}<div class="j-content">${({overview,exams,agenda,detail,watch,settings}[page]||overview)()}</div><footer class="j-footer">知国公 · 把每一步走稳。<span>本地记录与提醒助手 · 最终安排以招录机关公告为准</span></footer></div>`;
    }
    function createDialog(seed={},editing=false){const e=editing?current():seed;open(editing?'编辑考试档案':'添加一场考试',`<form id="journeyExamForm" class="j-form"><label>考试名称<input name="title" required maxlength="180" placeholder="例如：2027 湖北省考 · 武汉岗位" value="${h(e.title||'')}"></label><div class="j-formgrid"><label>考试年度<input name="year" pattern="20[0-9]{2}" required value="${h(e.year||String(new Date().getFullYear()+1))}" inputmode="numeric"></label><label>招录类型<select name="type">${options({'国考':'国考','省考':'省考','市级独立招录':'市级独立招录','其他公务员招录':'其他公务员招录'},e.type||'省考')}</select></label><label>地区<input name="region" maxlength="80" value="${h(e.region||'')}" placeholder="例如：湖北 / 武汉"></label><label>招录批次<input name="batch" maxlength="80" value="${h(e.batch||'统一招录')}"></label></div>${editing?'':`<label>流程时间模板<select name="template"><option value="blank">通用流程 · 时间待公布 / 自行核对填写</option><option value="national2027" ${e.template==='national2027'?'selected':''}>2027 国考 · 已核验报名与笔试时间</option></select></label><p class="j-muted">国考模板专业笔试需按岗位确认；省市考不套用国考时间。创建档案不会标记已报名。</p>`}<label>官方公告链接（可稍后补充）<input type="url" name="source" value="${h(e.source||'')}" placeholder="https://..."></label><details><summary>已选定岗位？填写双代码</summary><div class="j-formgrid"><label>部门 / 单位代码<input name="departmentCode" maxlength="40" value="${h(e.departmentCode||'')}"></label><label>职位代码<input name="positionCode" maxlength="40" value="${h(e.positionCode||'')}"></label></div><label>职位名称<input name="position" maxlength="200" value="${h(e.position||'')}"></label></details>${editing?`<label>档案备注<textarea name="note" maxlength="2000">${h(e.note)}</textarea></label>`:''}<button type="submit" class="j-btn primary">${editing?'保存档案':'创建考程'}</button></form>`,v=>{
        if(v.template==='national2027'&&(v.type!=='国考'||v.year!=='2027'))throw Error('2027国考时间模板只适用于 2027 年度国考，请修改类型 / 年度或选择通用流程。');
        if(!/^20\d{2}$/.test(v.year)||!v.title.trim())throw Error('请填写名称和有效年度');
        if(v.source&&!C.url(v.source))throw Error('来源需要有效的 http / https 链接');
        if(Boolean(v.departmentCode)!==Boolean(v.positionCode))throw Error('部门与职位代码需要成对填写');
        if(editing){if((v.year!==e.year||v.type!==e.type||v.batch!==e.batch)&&!confirm('变更年度、类型或批次不会调整已有日期。建议为新一轮另建考程；仍修改当前档案？'))return;Object.assign(e,v);}
        else{const n=C.createExam(v,root.ExamPolicy);if(data.exams.some(x=>C.identity(x)===C.identity(n)&&n.departmentCode))throw Error('该年度、批次及双代码已存在，请打开原档案');data.exams.push(n);activeId=n.id;}
        page='detail';pane='tasks';stage=-1;save();close();render();notify(editing?'档案已更新':'已建立考程，请逐项记录真实办理状态');
      });}
    function taskDialog(examId,taskId,newStage){const e=data.exams.find(e=>e.id===examId);if(!e)return;const fresh=!taskId,t=fresh?{id:C.uid(),title:'',hint:'自定义办理事项',stage:newStage,kind:'deadline',status:'todo',start:'',end:'',source:'',proof:'pending',note:'',place:'',completedAt:''}:e.tasks.find(x=>x.id===taskId);if(!t)return;
      open(fresh?'添加流程事项':t.title,`<form id="journeyTaskForm" class="j-form"><p class="j-muted">${h(e.title)}<br>${h(t.hint)}</p>${fresh?'<label>事项名称<input name="title" required maxlength="180"></label>':''}<div class="j-formgrid"><label>个人办理状态<select name="status">${options(C.states,t.status)}</select></label><label>事项类型<select name="kind">${options({deadline:'办理窗口 / 截止',exam:'考试 / 到场安排',opening:'开放查询（未公布截止）'},t.kind)}</select></label><label>开始（北京时间）<input type="datetime-local" name="start" value="${h(t.start)}"></label><label>结束 / 截止（北京时间）<input type="datetime-local" name="end" value="${h(t.end)}"></label></div><p class="j-muted">未公布请留空；原文 24:00 请填次日 00:00。考试到场事项需同时填写起止，才能检查冲突。</p><label>日期依据链接<input name="source" type="url" value="${h(t.source)}" placeholder="对应公告原文"></label><label>日期核对<select name="proof">${options({pending:'尚未核对，不导出日历',confirmed:'我已对照原文核对日期'},t.proof==='pending'?'pending':'confirmed')}</select></label><label>考点 / 办理地点<input name="place" maxlength="300" value="${h(t.place)}"></label><label>办理记录 / 原文要点<textarea name="note" maxlength="2000" placeholder="例如：已在报名系统查看缴费成功；或记录退回原因">${h(t.note)}</textarea></label><button type="submit" class="j-btn primary">保存此项</button></form>`,v=>{
        if(!C.validDates(v.start,v.end))throw Error('结束时间不能早于开始，且必须是有效日期');
        if(v.source&&!C.url(v.source))throw Error('请填写有效来源链接');
        if(v.proof==='confirmed'&&(v.start||v.end)&&!C.url(v.source))throw Error('核对日期需要保存对应公告链接');
        if(v.kind==='exam'&&Boolean(v.start)!==Boolean(v.end))throw Error('考试安排请同时填写起止时间；尚未发布可两项都留空');
        const unchanged=v.start===t.start&&v.end===t.end&&v.source===t.source&&v.proof==='confirmed';
        if(v.status==='done'&&t.start&&C.ms(t.start)>Date.now()&&C.trusted(t)&&!confirm('该事项的已核对开始时间尚未到。确认已经实际办妥？'))return;
        const builtin=t.proof==='builtin';Object.assign(t,v,{source:C.url(v.source),completedAt:v.status==='done'?(t.completedAt||new Date().toISOString()):''});if(builtin&&unchanged)t.proof='builtin';
        if(fresh)e.tasks.push(t);save();close();render();notify('已保存个人办理记录');
      });}
    function simpleDialog(type,id){const e=current();if(!e)return;
      if(type==='material'){const m=e.materials.find(x=>x.id===id)||{id:C.uid(),name:'',status:'todo',note:''};open('材料准备',`<form class="j-form"><label>材料名称<input name="name" required maxlength="180" value="${h(m.name)}"></label><label>准备状态<select name="status">${options({todo:'未准备',ready:'已备齐',submitted:'已提交',na:'不适用'},m.status)}</select></label><label>备注<textarea name="note" maxlength="2000">${h(m.note)}</textarea></label><button type="submit" class="j-btn primary">保存材料</button></form>`,v=>{Object.assign(m,v);if(!id)e.materials.push(m);save();close();render();});}
      if(type==='source'){const s=e.sources.find(x=>x.id===id)||{id:C.uid(),title:'',url:'',checked:'',note:''};open('保存公告与依据',`<form class="j-form"><label>公告标题<input name="title" required maxlength="180" value="${h(s.title)}"></label><label>原文链接<input name="url" type="url" required value="${h(s.url)}"></label><label>本人核对日期<input name="checked" type="date" value="${h(s.checked)}"></label><label>原文要点 / 对我的影响<textarea name="note" maxlength="2000" rows="6">${h(s.note)}</textarea></label><p class="j-muted">保存公告不会自动修改流程日期。核对后到流程清单更新对应事项。</p><button class="j-btn primary" type="submit">保存公告</button></form>`,v=>{if(!C.url(v.url))throw Error('请填写有效公告链接');if(v.checked&&(!C.date(v.checked)||v.checked>C.today()))throw Error('核对日期不能是未来');Object.assign(s,v);if(!id)e.sources.push(s);save();close();render();});}
      if(type==='score')open('成绩与复盘',`<form class="j-form"><div class="j-formgrid">${[['aptitude','行测'],['essay','申论'],['special','专业科目'],['interview','面试']].map(([k,label])=>`<label>${label}（百分制）<input name="${k}" type="number" min="0" max="100" step="0.01" value="${h(e.scores[k])}"></label>`).join('')}</div><label>官方结果（本人记录）<select name="result">${options(Object.fromEntries(['待公布','未进入面试','进入面试','待体检考察','拟录用公示','已收到录用通知','本次结束'].map(v=>[v,v])),e.scores.result)}</select></label><label>依据与复盘<textarea name="note" maxlength="2000" rows="6" placeholder="成绩来源；哪些能力进步了；失分原因；下一场如何调整">${h(e.scores.note)}</textarea></label><p class="j-muted">仅记录结果，不会自动完成其他流程。</p><button class="j-btn primary" type="submit">保存</button></form>`,v=>{Object.assign(e.scores,v);save();close();render();});
    }
    function studyDialog(error){const e=current();if(!e)return;open(error?'新增错题复盘卡':'记录一次学习',`<form class="j-form"><div class="j-formgrid"><label>学习日期<input name="date" type="date" required max="${C.today()}" value="${C.today()}"></label><label>科目<select name="subject">${options({'行测':'行测','申论':'申论','专业科目':'专业科目','面试':'面试'},'专业科目')}</select></label></div>${error?'<label>题目定位 / 知识点<input name="title" required maxlength="300" placeholder="题库名+题号，或简短知识点"></label>':'<div class="j-formgrid"><label>净学习分钟<input name="minutes" type="number" min="1" max="1440" required value="60"></label><label>练习题数<input name="count" type="number" min="0" max="5000" required value="0"></label><label>答对题数<input name="correct" type="number" min="0" max="5000" required value="0"></label></div>'}<label>${error?'错因与纠正方法':'本次收获与待改进'}<textarea name="note" maxlength="2000" rows="4" ${error?'required':''} placeholder="${error?'哪里想错了？下次看到什么条件应该怎么判断？':'写下实际完成内容，不用补打卡'}"></textarea></label><button type="submit" class="j-btn primary">保存记录</button></form>`,v=>{if(!C.date(v.date)||v.date>C.today())throw Error('请填写不晚于今天的有效日期');if(error)data.errors.push({...v,id:C.uid(),examId:e.id,round:0,next:C.addDays(v.date,1),mastered:false});else{const minutes=Number(v.minutes),count=Number(v.count),correct=Number(v.correct);if(!Number.isFinite(minutes)||minutes<=0||minutes>1440||!Number.isInteger(count)||!Number.isInteger(correct)||count<0||correct<0||correct>count)throw Error('请核对分钟与题数，答对数不能大于总数');data.logs.push({...v,id:C.uid(),examId:e.id,minutes,count,correct});}save();close();render();});}
    function importPreview(raw){const next=C.clean(raw);pendingImport=next;const collisions=next.exams.filter(e=>data.exams.some(x=>x.id===e.id||e.departmentCode&&C.identity(x)===C.identity(e)));open('预览考程备份',`<div class="j-callout">将读取 ${next.exams.length} 场考试、${next.logs.length} 条学习、${next.errors.length} 张错题。与本机重复的考试：${collisions.length} 场。</div><ul>${next.exams.map(e=>'<li>'+h(e.title)+' · '+h(e.year)+'</li>').join('')}</ul><p class="j-muted">导入前先导出当前备份。追加遇到重复考试会停止；覆盖会完整替换考程，不影响原有选岗收藏。</p><div class="j-actions">${button('backup','先备份本机')}${button('import-merge','追加导入','','primary')}${button('import-replace','覆盖恢复','','danger')}</div>`);}
    file.addEventListener('change',async()=>{try{const f=file.files?.[0];if(!f)return;if(f.size>8*1024*1024)throw Error('备份超过8MB');importPreview(JSON.parse(await f.text()));}catch(err){notify('导入失败：'+err.message);}finally{file.value='';}});
    function action(ev){const b=ev.target.closest('[data-j-action]');if(!b)return;const v=b.dataset.value,id=b.dataset.id,act=b.dataset.jAction;
      try{
        if(act==='close')return close();
        if(act==='page'){page=v;filter='all';render();}
        if(act.startsWith('go-')){page=act.slice(3);filter='all';render();}
        if(act==='create')createDialog();
        if(act==='open-exam'){activeId=b.dataset.exam;page='detail';pane='tasks';stage=-1;render();}
        if(act==='exam-filter'||act==='agenda-filter'){filter=v;render();}
        if(act==='pane'){pane=v;render();}
        if(act==='stage'){stage=Number(v);render();}
        if(act==='edit-exam')createDialog({},true);
        if(act==='edit-task')taskDialog(b.dataset.exam,b.dataset.task);
        if(act==='new-task')taskDialog(activeId,null,Number(b.dataset.stage));
        if(act==='archive'){const e=current();e.lifecycle=e.lifecycle==='active'?'archived':'active';save();render();notify(e.lifecycle==='archived'?'已归档，保留记录并停止该场待办提醒':'已恢复跟进');}
        if(act==='material-new'||act==='material-edit')simpleDialog('material',id);
        if(act==='source-new'||act==='source-edit')simpleDialog('source',id);
        if(act==='score-edit')simpleDialog('score');
        if(act==='log-new'||act==='error-new')studyDialog(act==='error-new');
        if(act==='log-delete'){if(!confirm('删除这条误记的学习记录？'))return;data.logs=data.logs.filter(x=>x.id!==id);save();render();}
        if(act==='review-ok'||act==='review-again'){const er=data.errors.find(x=>x.id===id);if(er){C.review(er,act==='review-ok');save();render();notify(er.mastered?'已完成三轮，保留复习记录':'下次复习：'+er.next);}}
        if(act==='watch-add'){const area=b.dataset.area;createDialog({title:area==='全国'?'2027 国考':area+'公务员招录 · 等待公告',region:area,type:area==='全国'?'国考':area==='深圳'?'市级独立招录':'省考',template:area==='全国'?'national2027':'blank',source:sources.find(x=>x[0]===area)[2]});}
        if(act==='backup')download('知国公-我的考程-'+C.today()+'.json',JSON.stringify(data,null,2));
        if(act==='calendar'){const result=C.ics(data);if(!result.count)return notify('暂无可导出节点。先补齐准确日期、来源，并勾选已核对。');download('知国公-考程提醒.ics',result.content,'text/calendar;charset=utf-8');notify(`已导出 ${result.count} 项；请导入系统日历并检查提醒权限。`);}
        if(act==='import')file.click();
        if(act==='import-merge'||act==='import-replace'){
          if(!pendingImport)return;
          if(act==='import-merge'){
            if(pendingImport.exams.some(e=>data.exams.some(x=>x.id===e.id||e.departmentCode&&C.identity(x)===C.identity(e))))throw Error('存在重复考试，请取消后整理备份，或选择完整覆盖恢复。');
            const merged={schema:1,exams:[...data.exams,...pendingImport.exams],logs:[...data.logs,...pendingImport.logs],errors:[...data.errors,...pendingImport.errors]};data=C.clean(merged);
          }else{if(!confirm('确认用此备份替换全部本机考程？建议先导出原记录。'))return;data=pendingImport;}
          storageError='';pendingImport=null;save();close();page='overview';render();notify('考程导入完成');
        }
        if(act==='print')root.print();
        if(act==='clear'){if(!confirm('清空本机全部考程、学习和错题记录？此操作不能撤销，请先导出备份。'))return;data=C.blank();storageError='';save();page='overview';render();notify('已清空考程记录');}
      }catch(err){if(modal.open)modal.querySelector('#journeyFormError').textContent=err.message;else notify(err.message);}
    }
    host.addEventListener('click',action);modal.addEventListener('click',action);
    root.addEventListener('storage',ev=>{if(ev.key===C.KEY){storageError='另一页面修改了考程。为避免覆盖，当前页已停止自动保存；请导出未保存内容后刷新。';render();}});
    document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!modal.open)render();});
    setInterval(()=>{if(!document.hidden&&!host.hidden&&!modal.open)render();},60000);
    render();
    return {
      render,
      snapshot:()=>JSON.parse(JSON.stringify(data)),
      importPreview,
      addJob(j){
        const e=C.fromJob(j,root.ExamPolicy),old=data.exams.find(x=>C.identity(x)===C.identity(e));
        if(old){activeId=old.id;notify('已存在这场岗位考程，打开原记录');}
        else{const same=data.exams.find(x=>x.lifecycle==='active'&&x.type==='国考'&&x.year===e.year&&x.batch===e.batch&&x.departmentCode);if(same){notify('本轮已有岗位考程。国考同轮报名须核对改报条件，请在原档案中编辑岗位或先归档。');return false;}data.exams.push(e);activeId=e.id;save();notify('已加入考程；实际报名与审核状态请自行确认。');}
        page='detail';pane='tasks';stage=-1;render();adapter.show?.();return true;
      }
    };
  }
  root.JourneyUI={mount};
})(window);
